// ---------------------------------------------------------------- NCT, tax, insurance, service
// These "compliance" reminders follow fixed notice rules (enforced by the database job
// process_due_reminders, migration 00032): notices before expiry, one on the last day, one
// the day after ("you don't have …"), then every Monday at 09:00 until a renewal is entered.

export const COMPLIANCE_TYPES = ['nct', 'road_tax', 'insurance', 'service'] as const;
export type ComplianceType = (typeof COMPLIANCE_TYPES)[number];
export const isComplianceType = (t: string): t is ComplianceType => (COMPLIANCE_TYPES as readonly string[]).includes(t);

/** Motor tax is sold for 3, 6 or 12 months. */
export const TAX_DURATIONS = [3, 6, 12] as const;

const isoRe = /^\d{4}-\d{2}-\d{2}$/;

/** Calendar month arithmetic on YYYY-MM-DD, clamping to the month's last day (31 Jan + 1 = 28/29 Feb). */
export function addMonthsIso(iso: string, months: number): string {
  const [y, m, d] = iso.split('-').map(Number);
  const total = y * 12 + (m - 1) + months;
  const ny = Math.floor(total / 12);
  const nm = total - ny * 12;
  const last = new Date(Date.UTC(ny, nm + 1, 0)).getUTCDate();
  return `${ny}-${String(nm + 1).padStart(2, '0')}-${String(Math.min(d, last)).padStart(2, '0')}`;
}

/** What we know about a car's age: the date of first registration if given, else the year. */
export type VehicleReg = { year: number | null; firstRegistrationDate?: string | null } | null;

/**
 * Days before expiry that each notice goes out (the last-day and expired notices come on top).
 * An NCT that runs out on the car's 10th anniversary gets an extra notice 120 days ahead (see
 * nctTenthAnniversary).
 */
export function noticeDaysBefore(type: ComplianceType, reg: VehicleReg = null, expiryIso: string | null = null): number[] {
  if (type === 'nct') return expiryIso && nctTenthAnniversary(reg, expiryIso) ? [120, 30, 7] : [30, 7];
  return type === 'insurance' ? [30, 7] : [14, 7];
}

// Official NCT rules (ncts.ie FAQ, "How is my NCT due date determined?"):
//  * Tests fall due on anniversaries of first registration: first at 4 years, then every
//    2 years, then every year from the 10th-anniversary test on. Cars aged 30–39 (not used
//    commercially) go back to every 2 years; cars 40+ aren't tested.
//  * A certificate runs from the pass date to the next due date, so testing on time (up to
//    90 days early) or late doesn't move the due dates.
//  * Voluntary early testing: passing MORE than 90 days before the due date gives a fresh
//    2-year (or 1-year, by age) certificate from the pass date. A car approaching its 10th
//    anniversary that passes more than 90 days early still gets 2 years — the last time.
// With the date of first registration ages are exact; with only the year they're counted in
// calendar years, and users can correct the suggested expiry to match their certificate.

/** Whole years old on `atIso` (null if we know nothing about the car's age). */
export function vehicleAge(reg: VehicleReg, atIso: string): number | null {
  const date = reg?.firstRegistrationDate;
  if (date && isoRe.test(date)) {
    const years = Number(atIso.slice(0, 4)) - Number(date.slice(0, 4));
    return atIso.slice(5) < date.slice(5) ? years - 1 : years;
  }
  return reg?.year != null ? Number(atIso.slice(0, 4)) - reg.year : null;
}

/** Certificate length for a car of this age at `atIso` (0 = not tested: 40+). */
export function nctTermYears(reg: VehicleReg, atIso: string): 0 | 1 | 2 {
  const age = vehicleAge(reg, atIso);
  if (age == null || age < 10) return 2;
  if (age < 30) return 1;
  return age < 40 ? 2 : 0;
}

/** The NCT runs out on the car's 10th anniversary: its last chance of a 2-year certificate. */
export function nctTenthAnniversary(reg: VehicleReg, expiryIso: string): boolean {
  return vehicleAge(reg, expiryIso) === 10;
}

/** Under 4 years old: no NCT yet. */
export function nctNotDueYet(reg: VehicleReg, todayIso: string): boolean {
  const age = vehicleAge(reg, todayIso);
  return age != null && age < 4;
}

/** 40 years and older: no NCT needed. */
export function nctExempt(reg: VehicleReg, todayIso: string): boolean {
  const age = vehicleAge(reg, todayIso);
  return age != null && age >= 40;
}

/** First NCT: the 4th anniversary of first registration (needs the date). */
export function nctFirstDue(reg: VehicleReg): string | null {
  const date = reg?.firstRegistrationDate;
  return date && isoRe.test(date) ? addMonthsIso(date, 48) : null;
}

/** Ages at which a test falls due: 4, 6, 8, then 10–29 yearly, then 30–38 every 2 years. */
const NCT_DUE_AGES = [4, 6, 8, ...Array.from({ length: 20 }, (_, i) => 10 + i), 30, 32, 34, 36, 38];

const daysBetween = (a: string, b: string) => Math.round((Date.parse(b) - Date.parse(a)) / 86_400_000);
const addDaysIso = (iso: string, days: number) => {
  const d = new Date(`${iso}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
};

/**
 * NCT expiry after a pass on `testDateIso`.
 *  * Renewal (previous expiry known): passed more than 90 days early → fresh certificate from
 *    the pass date; otherwise (on time or late) the next due date after the previous expiry.
 *  * First entry with the registration date: the next anniversary on the official schedule
 *    after the one this test was for (a test counts for a due date up to 90 days ahead).
 *  * First entry with only the year: from the pass date.
 * Returns '' for cars that aren't tested (40+).
 */
export function nctExpiryFromTest(reg: VehicleReg, testDateIso: string, previousExpiryIso?: string | null): string {
  if (previousExpiryIso && isoRe.test(previousExpiryIso)) {
    const voluntaryEarly = daysBetween(testDateIso, previousExpiryIso) > 90;
    const from = voluntaryEarly ? testDateIso : previousExpiryIso;
    const years = nctTermYears(reg, from);
    return years ? addMonthsIso(from, years * 12) : '';
  }
  const date = reg?.firstRegistrationDate;
  if (date && isoRe.test(date)) {
    const horizon = addDaysIso(testDateIso, 90);
    const dueDates = NCT_DUE_AGES.map((age) => addMonthsIso(date, age * 12));
    let i = -1;
    dueDates.forEach((d, j) => { if (d <= horizon) i = j; });
    if (i === -1) return addMonthsIso(testDateIso, 24); // tested before the 4th anniversary
    return dueDates[i + 1] ?? ''; // past 38: the next would be 40, which isn't tested
  }
  const years = nctTermYears(reg, testDateIso);
  return years ? addMonthsIso(testDateIso, years * 12) : '';
}

/** Last day to pass for the final 2-year certificate (more than 90 days before expiry). */
export function nctLastTwoYearDeadline(expiryIso: string): string {
  return addDaysIso(expiryIso, -91);
}

/** Plain-language summary of when the notices go out (shown under the form). */
export function noticeSummary(type: string, reg: VehicleReg = null, expiryIso: string | null = null): string {
  if (!isComplianceType(type)) return '';
  const days = noticeDaysBefore(type, reg, expiryIso);
  const list = days.length === 3 ? `${days[0]}, ${days[1]} and ${days[2]}` : `${days[0]} and ${days[1]}`;
  let extra = '';
  if (type === 'nct') {
    extra = expiryIso && nctTenthAnniversary(reg, expiryIso)
      ? ' Your car turns 10 when this NCT runs out: if it passes the test more than 90 days early, it gets a 2-year certificate for the last time. Otherwise it’s tested every year from then on.'
      : ' You can take the test up to 90 days early without losing any time on your certificate.';
  }
  return `We’ll remind you ${list} days before, on the last day, and every Monday morning after it runs out until you add the renewal.${extra}`;
}

/**
 * Fills in the dates a user didn't type: NCT expiry from the test date, insurance end from
 * start + length, tax start from end − length. Call before validating.
 */
export function completeReminderDates<T extends { reminderType: string; startDate: string; dueDate: string; durationMonths: string }>(
  f: T,
  reg: VehicleReg,
  previousExpiryIso?: string | null,
): T {
  const iso = (v: string) => isoRe.test(v);
  const months = Number(f.durationMonths) || 0;
  if (f.reminderType === 'nct' && iso(f.startDate) && !iso(f.dueDate)) return { ...f, dueDate: nctExpiryFromTest(reg, f.startDate, previousExpiryIso) };
  if (f.reminderType === 'nct' && !iso(f.startDate) && !iso(f.dueDate) && nctFirstDue(reg)) return { ...f, dueDate: nctFirstDue(reg)! };
  if (f.reminderType === 'insurance' && iso(f.startDate) && months && !iso(f.dueDate)) return { ...f, dueDate: addMonthsIso(f.startDate, months) };
  if (f.reminderType === 'road_tax' && iso(f.dueDate) && months) return { ...f, startDate: addMonthsIso(f.dueDate, -months) };
  return f;
}

const optionalIso = z.string().trim().regex(isoRe, 'Use the date picker').nullable().or(z.literal('').transform(() => null));

export const reminderSchema = z
  .object({
    reminderType: z.enum(reminderTypeValues),
    title: z.string().trim().max(120).optional().or(z.literal('')),
    /** NCT test date / insurance start / tax start. */
    startDate: optionalIso.optional().transform((v) => v ?? null),
    /** Expiry (NCT, tax, insurance) or due date (everything else). */
    dueDate: z.string().trim().regex(isoRe, 'A due date is required'),
    durationMonths: z.preprocess(
      (v) => (v === '' || v == null ? null : v),
      z.coerce.number().int().min(1).max(24).nullable(),
    ).optional().transform((v) => v ?? null),
    dueMileageKm: optionalPositiveInt,
    intervalMonths: z.coerce
      .number()
      .int()
      .min(1, 'Repeat interval must be at least 1 month')
      .max(120)
      .nullable()
      .or(z.literal('').transform(() => null)),
    notes: z.string().trim().max(1000).optional().or(z.literal('')),
  })
  .superRefine((v, ctx) => {
    const issue = (path: string, message: string) => ctx.addIssue({ code: z.ZodIssueCode.custom, path: [path], message });
    if (v.reminderType === 'road_tax' && !(TAX_DURATIONS as readonly number[]).includes(v.durationMonths ?? 0)) {
      issue('durationMonths', 'Choose 3, 6 or 12 months');
    }
    if (v.reminderType === 'insurance') {
      if (!v.startDate) issue('startDate', 'Enter the date the insurance started');
      if (!v.durationMonths) issue('durationMonths', 'Choose how long the policy runs');
    }
    if (v.startDate && v.startDate >= v.dueDate) issue('dueDate', 'The expiry date must be after the start date');
  })
  // Renewals replace the dates instead of repeating.
  .transform((v) => ({ ...v, intervalMonths: null }));

